import com.skillforge.platform.dto.ApiResponse;
import com.skillforge.platform.dto.AppendFilesRequest;
import com.skillforge.platform.entity.Skill;
import com.skillforge.platform.entity.SkillFile;
import com.skillforge.platform.entity.User;
import com.skillforge.platform.service.SkillService;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/skills/{skillId}/files")
public class SkillFileController {
    private final SkillService skillService;

    public SkillFileController(SkillService skillService) {
        this.skillService = skillService;
    }

    @PostMapping
    public ApiResponse<?> append(@PathVariable("skillId") Long skillId,
                                 @RequestBody AppendFilesRequest request) throws IOException {
        Skill skill = skillService.findById(skillId);
        if (skill == null) {
            return ApiResponse.error(404, "技能不存在");
        }
        User user = currentUser();
        if (!skillService.canModify(skill, user)) {
            return ApiResponse.error(403, "无权操作");
        }
        return ApiResponse.success(
                "文件添加成功",
                skillService.appendFiles(skill, request.getFiles(), user));
    }

    @GetMapping("/{fileId}/content")
    public ApiResponse<?> content(@PathVariable("skillId") Long skillId,
                                  @PathVariable("fileId") Long fileId) throws IOException {
        SkillFile file = skillService.findFile(fileId);
        if (file == null || !skillId.equals(file.getSkillId())) {
            return ApiResponse.error(404, "文件不存在");
        }
        Skill skill = skillService.findById(skillId);
        if (skill == null) {
            return ApiResponse.error(404, "文件不存在");
        }
        String content = skillService.readFile(skill, file);
        if (content == null) {
            return ApiResponse.error(404, "文件不存在");
        }

        Map<String, String> data = new LinkedHashMap<>();
        data.put("filePath", file.getFilePath());
        data.put("content", content);
        return ApiResponse.success(data);
    }

    private User currentUser() {
        return (User) SecurityContextHolder.getContext().getAuthentication().getPrincipal();
    }
}

